import{_ as a,o as i,c as o,a2 as r}from"./chunks/framework.Boholvbs.js";const p=JSON.parse('{"title":"WordPress.org Plugin Directory — Compliance Guidelines","description":"","frontmatter":{},"headers":[],"relativePath":"dev/wordpress-org-compliance/index.md","filePath":"dev/wordpress-org-compliance.md"}'),s={name:"dev/wordpress-org-compliance/index.md"};function l(t,e,n,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="wordpress-org-plugin-directory-—-compliance-guidelines" tabindex="-1">WordPress.org Plugin Directory — Compliance Guidelines <a class="header-anchor" href="#wordpress-org-plugin-directory-—-compliance-guidelines" aria-label="Permalink to &quot;WordPress.org Plugin Directory — Compliance Guidelines&quot;">​</a></h1><blockquote><p>Consolidado a partir das diretrizes oficiais do WordPress.org Plugin Directory.<br> Fonte: <a href="https://developer.wordpress.org/plugins/wordpress-org/detailed-plugin-guidelines/" target="_blank" rel="noreferrer">https://developer.wordpress.org/plugins/wordpress-org/detailed-plugin-guidelines/</a><br> Ultima atualizacao das diretrizes: Marco 2024</p></blockquote><hr><h2 id="_1-licenca" tabindex="-1">1. Licenca <a class="header-anchor" href="#_1-licenca" aria-label="Permalink to &quot;1. Licenca&quot;">​</a></h2><p><strong>Diretriz:</strong> Plugins must be compatible with the GNU General Public License v2 (or later).</p><ul><li>Todo o codigo, dados e imagens hospedados no diretorio WordPress.org devem ser compativeis com GPL ou GPL-Compatible.</li><li>Bibliotecas de terceiros incluidas tambem devem ser compativeis.</li><li>Recomendado: usar a mesma licenca do WordPress — GPLv2 or later.</li></ul><hr><h2 id="_2-responsabilidade-do-desenvolvedor" tabindex="-1">2. Responsabilidade do Desenvolvedor <a class="header-anchor" href="#_2-responsabilidade-do-desenvolvedor" aria-label="Permalink to &quot;2. Responsabilidade do Desenvolvedor&quot;">​</a></h2><p><strong>Diretriz:</strong> Developers are responsible for the contents and actions of their plugins.</p><ul><li>O desenvolvedor e o unico responsavel por garantir que todos os arquivos do plugin estejam em conformidade.</li><li>Escrever codigo intencionalmente para contornar diretrizes e proibido.</li><li>Antes de fazer upload para SVN, confirmar a licenca de todos os arquivos (codigo, imagens, bibliotecas).</li><li>Cumprir os termos de uso de todas as APIs e servicos de terceiros utilizados.</li></ul><hr><h2 id="_3-versao-estavel-disponivel" tabindex="-1">3. Versao Estavel Disponivel <a class="header-anchor" href="#_3-versao-estavel-disponivel" aria-label="Permalink to &quot;3. Versao Estavel Disponivel&quot;">​</a></h2><p><strong>Diretriz:</strong> A stable version of a plugin must be available from its WordPress Plugin Directory page.</p><ul><li>A unica versao distribuida pelo WordPress.org e a do diretorio.</li><li>Distribuir codigo por metodos alternativos sem manter o codigo hospedado atualizado pode resultar em remocao.</li><li>O trunk/readme.txt deve sempre refletir a versao atual do plugin.</li></ul><hr><h2 id="_4-codigo-legivel" tabindex="-1">4. Codigo Legivel <a class="header-anchor" href="#_4-codigo-legivel" aria-label="Permalink to &quot;4. Codigo Legivel&quot;">​</a></h2><p><strong>Diretriz:</strong> Code must be (mostly) human readable.</p><ul><li>Nao e permitido ofuscar codigo com tecnicas similares a p,a,c,k,e,r, uglify mangle, ou convencoes de nomes obscuras ($z12sdf813d).</li><li>O codigo-fonte deve estar incluido no plugin ou haver um link no readme para o local de desenvolvimento.</li><li>Recomendado documentar como usar as ferramentas de build.</li></ul><hr><h2 id="_5-sem-trialware" tabindex="-1">5. Sem Trialware <a class="header-anchor" href="#_5-sem-trialware" aria-label="Permalink to &quot;5. Sem Trialware&quot;">​</a></h2><p><strong>Diretriz:</strong> Trialware is not permitted.</p><ul><li>Funcionalidade nao pode ser restrita ou bloqueada, liberada apenas por pagamento ou upgrade.</li><li>Funcionalidade nao pode ser desabilitada apos periodo de trial ou quota atingida.</li><li>Plugins que fornecem apenas acesso sandbox a APIs tambem sao proibidos.</li><li>Permitido: upsell de produtos adicionais, desde que nao viole a diretriz 11 (hijacking).</li></ul><hr><h2 id="_6-software-as-a-service-saas-permitido" tabindex="-1">6. Software as a Service (SaaS) Permitido <a class="header-anchor" href="#_6-software-as-a-service-saas-permitido" aria-label="Permalink to &quot;6. Software as a Service (SaaS) Permitido&quot;">​</a></h2><p><strong>Diretriz:</strong> Software as a Service is permitted.</p><ul><li>Plugins que atuam como interface para servicos externos sao permitidos, mesmo pagos.</li><li>O servico deve ter funcionalidade de substancia e ser documentado no readme.</li><li>Nao permitido: <ul><li>Servico que existe apenas para validar licencas/keys.</li><li>Mover codigo arbitrario para fora do plugin para o servico parecer fornecer funcionalidade extra.</li><li>Storefronts que nao sao servicos.</li></ul></li></ul><hr><h2 id="_7-sem-rastreamento-sem-consentimento" tabindex="-1">7. Sem Rastreamento Sem Consentimento <a class="header-anchor" href="#_7-sem-rastreamento-sem-consentimento" aria-label="Permalink to &quot;7. Sem Rastreamento Sem Consentimento&quot;">​</a></h2><p><strong>Diretriz:</strong> Plugins may not track users without their consent.</p><ul><li>Plugins nao podem contatar servidores externos sem consentimento explicito e autorizado.</li><li>Exemplos proibidos: <ul><li>Coleta automatizada de dados do usuario sem confirmacao explicita.</li><li>Induzir usuarios a submeter informacao como requisito para usar o plugin.</li><li>Offloading de assets (imagens, scripts) nao relacionados a um servico.</li><li>Mecanismos de publicidade de terceiros que rastreiam uso/views.</li></ul></li><li>Excecao: SaaS como Twitter, Amazon CDN, Akismet — consentimento e implicito ao configurar.</li></ul><hr><h2 id="_8-sem-codigo-executavel-via-terceiros" tabindex="-1">8. Sem Codigo Executavel Via Terceiros <a class="header-anchor" href="#_8-sem-codigo-executavel-via-terceiros" aria-label="Permalink to &quot;8. Sem Codigo Executavel Via Terceiros&quot;">​</a></h2><p><strong>Diretriz:</strong> Plugins may not send executable code via third-party systems.</p><ul><li>Externamente carregar codigo de servicos documentados e permitido, mas a comunicacao deve ser segura.</li><li>Nao permitido: <ul><li>Instalar plugins, temas ou add-ons de servidores que nao sejam WordPress.org.</li><li>Instalar versoes premium do mesmo plugin.</li><li>Chamar CDN de terceiros por razoes que nao sejam inclusao de fontes; todo JS/CSS nao relacionado a servico deve ser incluido localmente.</li><li>Usar iframes para conectar paginas de admin; APIs devem ser usadas para minimizar riscos.</li></ul></li></ul><hr><h2 id="_9-legalidade-e-etica" tabindex="-1">9. Legalidade e Etica <a class="header-anchor" href="#_9-legalidade-e-etica" aria-label="Permalink to &quot;9. Legalidade e Etica&quot;">​</a></h2><p><strong>Diretriz:</strong> Developers and their plugins must not do anything illegal, dishonest, or morally offensive.</p><ul><li>Manipulacao artificial de resultados de busca (keyword stuffing, black hat SEO).</li><li>Oferecer aumento de trafego.</li><li>Compensar, enganar ou extorquir por reviews.</li><li>Criar contas falsas para reviews (sockpuppeting).</li><li>Utilizar recursos do servidor sem permissao (botnets, crypto-mining).</li></ul><hr><h2 id="_10-sem-links-creditos-externos-sem-permissao" tabindex="-1">10. Sem Links/Creditos Externos Sem Permissao <a class="header-anchor" href="#_10-sem-links-creditos-externos-sem-permissao" aria-label="Permalink to &quot;10. Sem Links/Creditos Externos Sem Permissao&quot;">​</a></h2><p><strong>Diretriz:</strong> Plugins may not embed external links or credits on the public site without explicitly asking the user&#39;s permission.</p><ul><li>Nao adicionar links ou creditos no frontend sem opt-in explicito do usuario.</li></ul><hr><h2 id="_11-nao-hijack-o-dashboard" tabindex="-1">11. Nao Hijack o Dashboard <a class="header-anchor" href="#_11-nao-hijack-o-dashboard" aria-label="Permalink to &quot;11. Nao Hijack o Dashboard&quot;">​</a></h2><p><strong>Diretriz:</strong> Plugins should not hijack the admin dashboard.</p><ul><li>Nao adicionar widgets obrigatorios, notificacoes intrusivas, ou redirecionamentos forcados apos ativacao.</li><li>Upsell deve ser moderado e nao interferir na experiencia de admin.</li></ul><hr><h2 id="_12-readme-sem-spam" tabindex="-1">12. Readme Sem Spam <a class="header-anchor" href="#_12-readme-sem-spam" aria-label="Permalink to &quot;12. Readme Sem Spam&quot;">​</a></h2><p><strong>Diretriz:</strong> Public facing pages on WordPress.org (readmes) must not spam.</p><ul><li>Maximo de 12 tags.</li><li>Sem affiliate links desnecessarios.</li><li>Sem tags de plugins concorrentes.</li><li>Sem keyword stuffing ou blackhat SEO.</li><li>Readmes devem ser escritos para pessoas, nao bots.</li><li>Links afiliados devem ser divulgados e apontar diretamente para o servico.</li></ul><hr><h2 id="_13-usar-bibliotecas-padrao-do-wordpress" tabindex="-1">13. Usar Bibliotecas Padrao do WordPress <a class="header-anchor" href="#_13-usar-bibliotecas-padrao-do-wordpress" aria-label="Permalink to &quot;13. Usar Bibliotecas Padrao do WordPress&quot;">​</a></h2><p><strong>Diretriz:</strong> Plugins must use WordPress&#39; default libraries.</p><ul><li>WordPress inclui jQuery, Atom Lib, SimplePie, PHPMailer, PHPass, etc.</li><li>Plugins nao podem incluir essas bibliotecas no proprio codigo.</li><li>Devem usar as versoes empacotadas com o WordPress.</li></ul><hr><h2 id="_14-evitar-commits-frequentes" tabindex="-1">14. Evitar Commits Frequentes <a class="header-anchor" href="#_14-evitar-commits-frequentes" aria-label="Permalink to &quot;14. Evitar Commits Frequentes&quot;">​</a></h2><p><strong>Diretriz:</strong> Frequent commits to a plugin should be avoided.</p><ul><li>O repositorio SVN e de release, nao de desenvolvimento.</li><li>Apenas codigo pronto para deploy deve ser enviado.</li><li>Commits rapidos e repetidos que apenas ajustam aspectos menores podem ser vistos como gaming da lista Recently Updated.</li></ul><hr><h2 id="_15-incrementar-versao-a-cada-release" tabindex="-1">15. Incrementar Versao a Cada Release <a class="header-anchor" href="#_15-incrementar-versao-a-cada-release" aria-label="Permalink to &quot;15. Incrementar Versao a Cada Release&quot;">​</a></h2><p><strong>Diretriz:</strong> Plugin version numbers must be incremented for each new release.</p><ul><li>Usuarios so sao alertados de updates quando a versao aumenta.</li><li>O readme.txt do trunk deve sempre refletir a versao atual.</li></ul><hr><h2 id="_16-plugin-completo-na-submissao" tabindex="-1">16. Plugin Completo na Submissao <a class="header-anchor" href="#_16-plugin-completo-na-submissao" aria-label="Permalink to &quot;16. Plugin Completo na Submissao&quot;">​</a></h2><p><strong>Diretriz:</strong> A complete plugin must be available at the time of submission.</p><ul><li>Nao e possivel reservar nomes para uso futuro.</li><li>Um zip completo e exigido na submissao.</li></ul><hr><h2 id="_17-respeitar-marcas-registradas" tabindex="-1">17. Respeitar Marcas Registradas <a class="header-anchor" href="#_17-respeitar-marcas-registradas" aria-label="Permalink to &quot;17. Respeitar Marcas Registradas&quot;">​</a></h2><p><strong>Diretriz:</strong> Plugins must respect trademarks, copyrights, and project names.</p><ul><li>Nao usar marcas registradas ou nomes de outros projetos como termo inicial do slug.</li><li>Exemplo: nao usar wordpress no slug.</li></ul><hr><h2 id="requisitos-adicionais-de-seguranca-e-privacidade" tabindex="-1">Requisitos Adicionais de Seguranca e Privacidade <a class="header-anchor" href="#requisitos-adicionais-de-seguranca-e-privacidade" aria-label="Permalink to &quot;Requisitos Adicionais de Seguranca e Privacidade&quot;">​</a></h2><h3 id="seguranca" tabindex="-1">Seguranca <a class="header-anchor" href="#seguranca" aria-label="Permalink to &quot;Seguranca&quot;">​</a></h3><ul><li>Todo input do usuario deve ser validado e sanitizado.</li><li>Todo output deve ser escapado.</li><li>Usar nonces para proteger acoes.</li><li>Verificar capabilities antes de executar acoes administrativas.</li><li>Nao gerar notices/warnings com WP_DEBUG ativado.</li></ul><h3 id="privacidade" tabindex="-1">Privacidade <a class="header-anchor" href="#privacidade" aria-label="Permalink to &quot;Privacidade&quot;">​</a></h3><ul><li>Plugins que coletam, usam, armazenam ou passam dados pessoais a terceiros devem usar wp_add_privacy_policy_content().</li><li>Devem fornecer callbacks de Personal Data Exporter e Personal Data Eraser quando aplicavel.</li><li>Devem documentar quais dados sao coletados, como sao usados e com quem sao compartilhados.</li></ul><h3 id="plugin-check-pcp" tabindex="-1">Plugin Check (PCP) <a class="header-anchor" href="#plugin-check-pcp" aria-label="Permalink to &quot;Plugin Check (PCP)&quot;">​</a></h3><ul><li>O WordPress.org exige que novos plugins passem no Plugin Check antes da aprovaao.</li><li>Plugins re-listados apos problemas de seguranca tambem devem passar nos checks de seguranca.</li><li>O PCP verifica: seguranca, performance, acessibilidade, i18n, e conformidade com diretrizes.</li></ul><hr><h2 id="checklist-de-submissao" tabindex="-1">Checklist de Submissao <a class="header-anchor" href="#checklist-de-submissao" aria-label="Permalink to &quot;Checklist de Submissao&quot;">​</a></h2><ul><li>[ ] Licenca GPL compativel (GPLv2 ou later)</li><li>[ ] readme.txt valido com todos os headers obrigatorios</li><li>[ ] Codigo legivel, nao ofuscado</li><li>[ ] Sem trialware</li><li>[ ] Sem tracking sem consentimento explicito</li><li>[ ] Sem codigo executavel de terceiros (exceto SaaS documentado)</li><li>[ ] Sem hijack de dashboard</li><li>[ ] Maximo 12 tags no readme</li><li>[ ] Usa bibliotecas padrao do WordPress (nao inclui jQuery, etc.)</li><li>[ ] Versao incrementada</li><li>[ ] Plugin completo e funcional</li><li>[ ] Nome do plugin nao viola marcas registradas</li><li>[ ] Seguranca: input sanitizado, output escapado, nonces, capabilities</li><li>[ ] Privacidade: wp_add_privacy_policy_content() se aplicavel</li><li>[ ] Passa no Plugin Check (PCP)</li></ul>',81)])])}const g=a(s,[["render",l]]);export{p as __pageData,g as default};
